import{_ as c}from"./plugin-vue_export-helper-c27b6911.js";import{r as a,o as i,c as n,d as l,a as d,b as t,e as o,f as r}from"./app-12b563a2.js";const s={},h=d("p",null,"Neovim 的入门难点，是同一个按键会随着模式改变作用。理解这个规则，再掌握少量可以组合的编辑命令，就能完成日常编辑。",-1),p=d("p",null,[t("这篇文章面向已经能在终端启动 "),d("code",null,"nvim"),t(" 的初学者。你可以跟着练习完成第一次编辑，也可以在日常使用时查找快捷键。")],-1),m=r(`<h2 id="阅读导航" tabindex="-1"><a class="header-anchor" href="#阅读导航" aria-hidden="true">#</a> 阅读导航</h2><ul><li><a href="#%E5%BF%AB%E6%8D%B7%E9%94%AE%E9%80%9F%E6%9F%A5">快捷键速查</a>：按操作分类，查按键、作用、英文助记和适用模式。</li><li><a href="#%E4%BB%8E%E5%A4%B4%E5%AD%A6%E4%B9%A0">从头学习</a>：用一份练习文件走完输入、修改、搜索、保存和分屏流程。</li><li><a href="#%E8%BF%9B%E9%98%B6%E7%90%86%E8%A7%A3">进阶理解</a>：认识操作符、文本对象、语言服务与内置终端。</li><li><a href="#%E5%B8%B8%E8%A7%81%E9%97%AE%E9%A2%98">常见问题</a>：根据实际现象定位问题。</li><li><a href="#%E7%BB%A7%E7%BB%AD%E7%BB%83%E4%B9%A0%E4%B8%8E%E5%8F%82%E8%80%83">继续练习与参考</a>：内置教程、学习清单与官方文档。</li><li><a href="#%E9%99%84%E5%BD%95">附录</a>：作者的安装环境、全局定制与验证范围。</li></ul><p><strong>适用范围</strong>：原生条目适用于 Neovim；标注 <strong>LazyVim</strong> 的组合键需要相应配置。正文练习可以在普通终端中完成，也可以通过 Paseo 终端连接到主机操作。本文以 Neovim 0.12.6、LazyVim 16.0.2 为核对环境，具体记录见附录。</p><h2 id="快捷键速查" tabindex="-1"><a class="header-anchor" href="#快捷键速查" aria-hidden="true">#</a> 快捷键速查</h2><ul><li><strong>编辑文字</strong>：<a href="#%E8%BE%93%E5%85%A5">输入</a> · <a href="#%E7%A7%BB%E5%8A%A8">移动</a> · <a href="#%E4%BF%AE%E6%94%B9%E4%B8%8E%E5%A4%8D%E5%88%B6">修改与复制</a> · <a href="#%E9%80%89%E6%8B%A9">选择</a></li><li><strong>管理文件</strong>：<a href="#%E4%BF%9D%E5%AD%98%E4%B8%8E%E9%80%80%E5%87%BA">保存与退出</a> · <a href="#%E6%90%9C%E7%B4%A2%E4%B8%8E%E6%9B%BF%E6%8D%A2">搜索与替换</a> · <a href="#%E6%96%87%E4%BB%B6%E4%B8%8E%E7%AA%97%E5%8F%A3">文件与窗口</a></li><li><strong>辅助功能</strong>：<a href="#%E4%BB%A3%E7%A0%81%E4%B8%8E%E8%A1%A5%E5%85%A8">代码与补全</a> · <a href="#%E5%86%85%E7%BD%AE%E7%BB%88%E7%AB%AF">内置终端</a> · <a href="#%E5%B8%AE%E5%8A%A9">帮助</a></li></ul><p>使用速查表时注意：</p><ul><li><code>gg</code>、<code>ciw</code>、<code>空格 → f → f</code> 都是<strong>依次按</strong>；<code>Ctrl+r</code> 是<strong>同时按</strong>。</li><li>大小写有区别。<code>G</code> 通常用 <code>Shift+g</code> 输入。</li><li>表中的 <code>/</code> 有时用于分隔可选按键，例如 <code>h / j / k / l</code>，每次选一个按。</li><li>冒号命令及 <code>/关键词</code>、<code>?关键词</code> 都要按回车确认。其他普通模式组合通常直接执行。</li><li>英文列提供助记词或动作名称；约定键位不一定对应英文首字母。详细读法见<a href="#_3-%E7%9C%8B%E6%87%82%E6%8C%89%E9%94%AE%E8%AE%B0%E6%B3%95">看懂按键记法</a>。</li></ul><p>“原生”表示 Neovim 自带；“LazyVim”表示本文环境沿用的官方默认映射。作者为全局安装新增的维护设置另列在附录。</p><h3 id="输入" tabindex="-1"><a class="header-anchor" href="#输入" aria-hidden="true">#</a> 输入</h3><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>i</code></td><td>在光标前输入</td><td>Insert</td><td>普通 → 插入；原生</td></tr><tr><td><code>a</code></td><td>在光标后输入</td><td>Append</td><td>普通 → 插入；原生</td></tr><tr><td><code>I</code></td><td>从行内首个非空白字符前输入</td><td>Insert</td><td>普通 → 插入；原生</td></tr><tr><td><code>A</code></td><td>在行尾输入</td><td>Append</td><td>普通 → 插入；原生</td></tr><tr><td><code>o / O</code></td><td>在下面／上面新建一行并输入</td><td>Open a new line</td><td>普通 → 插入；原生</td></tr><tr><td><code>Esc</code></td><td>结束输入或取消选择、命令输入</td><td>Escape</td><td>插入、可视、命令行等；原生</td></tr><tr><td><code>Ctrl+[</code></td><td>结束插入或替换的另一种按法</td><td>Escape 等效操作</td><td>插入、替换；原生</td></tr></tbody></table><p>LazyVim 给 <code>Esc</code> 增加了清除搜索高亮、停止代码片段等行为。内置终端的退出方法见<a href="#%E5%86%85%E7%BD%AE%E7%BB%88%E7%AB%AF">内置终端</a>。</p><h3 id="移动" tabindex="-1"><a class="header-anchor" href="#移动" aria-hidden="true">#</a> 移动</h3><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>h / j / k / l</code></td><td>左／下／上／右移动</td><td>Left / Down / Up / Right</td><td>普通、可视；原生</td></tr><tr><td><code>w</code></td><td>向前到下一单词开头</td><td>Word</td><td>普通、可视；原生</td></tr><tr><td><code>b</code></td><td>向后到单词开头</td><td>Back</td><td>普通、可视；原生</td></tr><tr><td><code>e</code></td><td>到单词末尾</td><td>End of word</td><td>普通、可视；原生</td></tr><tr><td><code>0</code></td><td>到行的最开头</td><td>约定键位</td><td>普通、可视；原生</td></tr><tr><td><code>^</code></td><td>到行内首个非空白字符</td><td>约定键位</td><td>普通、可视；原生</td></tr><tr><td><code>$</code></td><td>到行尾</td><td>End of line</td><td>普通、可视；原生</td></tr><tr><td><code>gg / G</code></td><td>到文件开头／末尾</td><td>Go to first / last line</td><td>普通；原生</td></tr><tr><td><code>20G</code></td><td>到第 20 行，数字可替换</td><td>Go to line</td><td>普通；原生</td></tr><tr><td><code>5j / 3w</code></td><td>下移五行／前移三个单词</td><td>Count + motion</td><td>普通；原生</td></tr><tr><td><code>Ctrl+d / Ctrl+u</code></td><td>向下／向上滚动半屏</td><td>Down / Up</td><td>普通；原生</td></tr><tr><td><code>fa</code></td><td>找当前行后面的下一个字母 a</td><td>Find</td><td>普通；原生</td></tr><tr><td><code>%</code></td><td>在配对括号之间跳转</td><td>Match，约定键位</td><td>普通；原生</td></tr><tr><td><code>Alt+j / Alt+k</code></td><td>向下／向上移动当前行或所选多行</td><td>Move down / up</td><td>普通、插入、可视；LazyVim</td></tr></tbody></table><p>LazyVim 对 <code>j/k</code> 有显示行增强：单按时照顾屏幕折行，带数字时按实际文件行移动。<code>w/b/e</code> 按编辑器的单词边界工作；中文连续文本的跳转不等同中文分词。</p><h3 id="修改与复制" tabindex="-1"><a class="header-anchor" href="#修改与复制" aria-hidden="true">#</a> 修改与复制</h3><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>d / y / c</code></td><td>开始删除／复制／修改，等待范围</td><td>Delete / Yank / Change</td><td>普通 → 等待范围；原生</td></tr><tr><td><code>dd / yy</code></td><td>剪切／复制当前整行</td><td>Delete / Yank</td><td>普通；原生</td></tr><tr><td><code>cc</code></td><td>修改当前整行，保留缩进并输入</td><td>Change</td><td>普通 → 插入；原生</td></tr><tr><td><code>dw / d$</code></td><td>从光标删到下一词开头／行尾</td><td>Delete + motion</td><td>普通；原生</td></tr><tr><td><code>y$</code></td><td>从光标复制到行尾</td><td>Yank + motion</td><td>普通；原生</td></tr><tr><td><code>diw</code></td><td>删除整个当前单词</td><td>Delete inner word</td><td>普通；原生</td></tr><tr><td><code>ciw</code></td><td>替换整个当前单词并开始输入</td><td>Change inner word</td><td>普通 → 插入；原生</td></tr><tr><td><code>yiw</code></td><td>复制整个当前单词</td><td>Yank inner word</td><td>普通；原生</td></tr><tr><td><code>ci&quot;</code></td><td>替换双引号里面的内容</td><td>Change inside quotes</td><td>普通 → 插入；原生</td></tr><tr><td><code>3dd</code></td><td>从当前行开始剪切三行</td><td>Count + Delete</td><td>普通；原生</td></tr><tr><td><code>x</code></td><td>删除光标下一个字符</td><td>Delete character，约定键位</td><td>普通；原生</td></tr><tr><td><code>rX</code></td><td>把光标下一个字符换成 X</td><td>Replace</td><td>普通；原生</td></tr><tr><td><code>R</code></td><td>连续覆盖输入，直到按 Esc</td><td>Replace mode</td><td>普通 → 替换；原生</td></tr><tr><td><code>p / P</code></td><td>在后面／前面粘贴</td><td>Put</td><td>普通；原生</td></tr><tr><td><code>u / Ctrl+r</code></td><td>撤销／重做编辑</td><td>Undo / Redo</td><td>普通；原生</td></tr><tr><td><code>.</code></td><td>在新位置重复上一次修改</td><td>Repeat last change</td><td>普通；原生</td></tr></tbody></table><p><code>rX</code> 中的 <code>X</code> 是示例替换字符。粘贴整行时，<code>p/P</code> 分别放到当前行下面／上面；字符内容则放到光标后面／前面。删除也会更新寄存器，后续 <code>p</code> 可能粘贴最近删除的内容。组合原理见<a href="#%E6%93%8D%E4%BD%9C%E7%AC%A6%E4%B8%8E%E6%96%87%E6%9C%AC%E5%AF%B9%E8%B1%A1">操作符与文本对象</a>。</p><h3 id="选择" tabindex="-1"><a class="header-anchor" href="#选择" aria-hidden="true">#</a> 选择</h3><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>v</code></td><td>按字符选择</td><td>Visual</td><td>普通 → 可视；原生</td></tr><tr><td><code>V</code></td><td>按整行选择</td><td>Visual line</td><td>普通 → 可视；原生</td></tr><tr><td><code>Ctrl+v</code></td><td>选择矩形区域</td><td>Visual block</td><td>普通 → 可视；原生</td></tr><tr><td><code>y / d</code></td><td>复制／剪切选区，返回普通模式</td><td>Yank / Delete</td><td>可视；原生</td></tr><tr><td><code>c</code></td><td>删除选区并输入替换文字</td><td>Change</td><td>可视 → 插入；原生</td></tr><tr><td><code>&gt; / &lt;</code></td><td>增加／减少选中行的缩进</td><td>Indent / Unindent</td><td>可视；原生，LazyVim 保留选区</td></tr><tr><td><code>Esc</code></td><td>取消选择</td><td>Escape</td><td>可视 → 普通；原生</td></tr></tbody></table><p><code>Ctrl+v</code> 必须传递到 Neovim 才能触发矩形选择。跨应用剪贴板和客户端特殊按键见<a href="#%E5%AE%A2%E6%88%B7%E7%AB%AF%E4%B8%8E%E9%AA%8C%E8%AF%81%E8%8C%83%E5%9B%B4">客户端与验证范围</a>。</p><h3 id="保存与退出" tabindex="-1"><a class="header-anchor" href="#保存与退出" aria-hidden="true">#</a> 保存与退出</h3><p>以下冒号命令从普通模式开始输入，最后按回车。</p><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>:w</code></td><td>保存当前文件</td><td>Write</td><td>命令行；原生</td></tr><tr><td><code>:w notes.md</code></td><td>首次给空白 Buffer 命名并保存</td><td>Write</td><td>命令行；原生</td></tr><tr><td><code>:saveas other.md</code></td><td>另存新文件并切换当前文件名，旧文件保留</td><td>Save as</td><td>命令行；原生</td></tr><tr><td><code>:q</code></td><td>关闭当前窗口，未保存时可能提示</td><td>Quit</td><td>命令行；原生</td></tr><tr><td><code>:wq</code></td><td>保存当前文件并关闭当前窗口</td><td>Write + Quit</td><td>命令行；原生</td></tr><tr><td><code>:q!</code></td><td>不写入磁盘，强制关闭当前窗口</td><td>Quit without writing</td><td>命令行；原生</td></tr><tr><td><code>:wa</code></td><td>保存全部可写且已命名的修改 Buffer</td><td>Write all</td><td>命令行；原生</td></tr><tr><td><code>:wqa</code></td><td>全部保存成功后退出所有窗口</td><td>Write + Quit all</td><td>命令行；原生</td></tr><tr><td><code>Ctrl+s</code></td><td>保存并返回普通模式</td><td>Save</td><td>普通、插入、可视；LazyVim</td></tr><tr><td><code>:pwd</code></td><td>查看当前工作目录</td><td>Print working directory</td><td>命令行；原生</td></tr><tr><td><code>:cd ~/nvim-practice</code></td><td>切换到练习目录</td><td>Change directory</td><td>命令行；原生</td></tr></tbody></table><blockquote><p><strong>记住</strong>：<code>:q!</code> 首先是关闭窗口的命令。同一 Buffer 仍在另一窗口显示时，未保存内容可以继续保留。它也不会回退已经写入磁盘的内容。</p></blockquote><p>具体例子见<a href="#_7-%E5%90%8C%E4%B8%80%E7%BC%93%E5%86%B2%E5%8C%BA%E7%9A%84%E5%A4%9A%E4%B8%AA%E7%AA%97%E5%8F%A3">同一缓冲区的多个窗口</a>。</p><p>未命名 Buffer 可以用 <code>:w notes.md</code> 第一次命名；已命名 Buffer 执行 <code>:w other.md</code> 是向另一个文件写入内容，切换当前文件名使用 <code>:saveas</code>。保存失败时先处理提示，确认后再退出。</p><h3 id="搜索与替换" tabindex="-1"><a class="header-anchor" href="#搜索与替换" aria-hidden="true">#</a> 搜索与替换</h3><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>/关键词</code>，回车</td><td>向文件后面搜索</td><td>Search forward</td><td>普通 → 命令行；原生</td></tr><tr><td><code>?关键词</code>，回车</td><td>向文件前面搜索</td><td>Search backward</td><td>普通 → 命令行；原生</td></tr><tr><td><code>n / N</code></td><td>跳到后一个／前一个匹配</td><td>Next / Previous</td><td>普通；LazyVim 的方向约定</td></tr><tr><td><code>Esc</code></td><td>清除搜索高亮</td><td>Clear search highlight</td><td>普通；LazyVim</td></tr><tr><td><code>:%s/old/new/gc</code></td><td>全文件逐项确认替换</td><td>Substitute</td><td>命令行；原生</td></tr><tr><td><code>y / n / q</code></td><td>确认替换／跳过／结束替换</td><td>Yes / No / Quit</td><td>替换确认中；原生</td></tr></tbody></table><p>在原生 Neovim 中，<code>n/N</code> 方向跟随上一次搜索方向；本文 LazyVim 环境把 <code>n</code> 固定为向后面的匹配移动，<code>N</code> 为向前面的匹配移动。搜索词使用正则表达式，初学先用普通文字。</p><p>替换命令中：<code>%</code> 表示当前文件全部行，<code>s</code> 是 Substitute，<code>g</code> 表示每行的所有匹配，<code>c</code> 表示 Confirm、逐项确认。其范围是当前文件。</p><h3 id="文件与窗口" tabindex="-1"><a class="header-anchor" href="#文件与窗口" aria-hidden="true">#</a> 文件与窗口</h3><p><strong>文件与 Buffer</strong></p><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>:e notes.md</code></td><td>打开文件；不存在时准备新 Buffer</td><td>Edit</td><td>命令行；原生</td></tr><tr><td><code>:ls</code></td><td>列出已打开的 Buffer</td><td>List</td><td>命令行；原生</td></tr><tr><td><code>:bnext / :bprevious</code></td><td>切到后一个／前一个 Buffer</td><td>Buffer next / previous</td><td>命令行；原生</td></tr><tr><td><code>空格 → f → f</code></td><td>查找项目文件</td><td>Find Files</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → f → F</code></td><td>查找当前工作目录的文件</td><td>Find Files in cwd</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → f → r</code></td><td>打开最近文件列表</td><td>Recent files</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → f → n</code></td><td>新建空白 Buffer</td><td>File + New</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → e</code></td><td>打开或关闭文件目录树</td><td>Explorer</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → s → g</code></td><td>在项目中按文字内容搜索</td><td>Search + Grep</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → ,</code></td><td>列出并切换已打开的文件</td><td>Buffers，约定键位</td><td>普通；LazyVim</td></tr><tr><td><code>[b / ]b</code> 或 <code>H / L</code></td><td>切到前一个／后一个 Buffer</td><td>Previous / Next Buffer</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → b → d</code></td><td>关闭当前 Buffer，磁盘文件保留</td><td>Buffer + Delete</td><td>普通；LazyVim</td></tr></tbody></table><p><strong>窗口与标签页</strong></p><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>:vsplit</code></td><td>将当前 Buffer 左右分屏显示</td><td>Vertical split</td><td>命令行；原生</td></tr><tr><td><code>:split</code></td><td>将当前 Buffer 上下分屏显示</td><td>Split</td><td>命令行；原生</td></tr><tr><td><code>空格 → -</code></td><td>上下分屏，新窗口在下方</td><td>Split below</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → |</code></td><td>左右分屏，新窗口在右方</td><td>Split right</td><td>普通；LazyVim</td></tr><tr><td><code>Ctrl+h/j/k/l</code></td><td>切换到左／下／上／右窗口</td><td>Go to window</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → w → d</code></td><td>关闭当前窗口</td><td>Window + Delete</td><td>普通；LazyVim</td></tr><tr><td><code>空格 → w → m</code></td><td>切换当前窗口的放大显示</td><td>Window maximize / zoom</td><td>普通；LazyVim</td></tr><tr><td><code>:tabnew</code></td><td>新建一组标签页布局</td><td>Tab new</td><td>命令行；原生</td></tr><tr><td><code>gt / gT</code></td><td>切到下一个／上一个标签页</td><td>Go to tab</td><td>普通；原生</td></tr></tbody></table><p><code>H/L</code> 是大写字母，常写作 <code>&lt;S-h&gt;/&lt;S-l&gt;</code>；这里的切换 Buffer 行为来自 LazyVim。<code>ff</code> 根据项目根目录查找，<code>fF</code> 根据 cwd 查找，二者范围可能不同。</p><h3 id="代码与补全" tabindex="-1"><a class="header-anchor" href="#代码与补全" aria-hidden="true">#</a> 代码与补全</h3><p>跳转、重命名和代码操作需要当前语言的服务提供相应能力；格式化需要对应工具。配置边界见<a href="#%E4%BB%A3%E7%A0%81%E8%83%BD%E5%8A%9B%E7%9A%84%E4%B8%89%E4%B8%AA%E7%BB%84%E6%88%90">代码能力的三个组成</a>。</p><p><strong>代码导航与修改</strong></p><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>gd</code></td><td>跳转到定义</td><td>Go to Definition</td><td>普通；需语言服务；LazyVim</td></tr><tr><td><code>gr</code></td><td>查找引用位置</td><td>References</td><td>普通；需语言服务；LazyVim</td></tr><tr><td><code>Ctrl+o</code></td><td>返回之前的跳转位置</td><td>Older position</td><td>普通；原生</td></tr><tr><td><code>K</code></td><td>查看符号说明</td><td>Hover，约定键位</td><td>普通；需语言服务；LazyVim</td></tr><tr><td><code>空格 → c → r</code></td><td>重命名变量、函数等符号</td><td>Code + Rename</td><td>普通；需语言服务；LazyVim</td></tr><tr><td><code>空格 → c → a</code></td><td>查看代码操作、修复建议</td><td>Code Action</td><td>普通、可视；需相应能力；LazyVim</td></tr><tr><td><code>空格 → c → f</code></td><td>格式化当前文件或选区</td><td>Code + Format</td><td>普通、可视；需格式化工具；LazyVim</td></tr><tr><td><code>[d / ]d</code></td><td>跳到上一个／下一个诊断</td><td>Previous / Next Diagnostic</td><td>普通；需诊断信息；LazyVim</td></tr></tbody></table><p><strong>补全菜单与代码片段</strong></p><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>Ctrl+n / Ctrl+p</code> 或方向键</td><td>选择下一项／上一项补全</td><td>Next / Previous</td><td>插入且有补全菜单；LazyVim</td></tr><tr><td><code>Enter</code></td><td>接受选中的补全项</td><td>Accept</td><td>插入且有可接受项；LazyVim</td></tr><tr><td><code>Ctrl+y</code></td><td>选中并接受补全项</td><td>Select and accept</td><td>插入且有补全菜单；LazyVim</td></tr><tr><td><code>Ctrl+e</code></td><td>取消补全菜单</td><td>Cancel</td><td>插入且有补全菜单；LazyVim</td></tr><tr><td><code>Tab / Shift+Tab</code></td><td>在片段占位符间前进／后退</td><td>Snippet forward / backward</td><td>活动代码片段中；LazyVim</td></tr></tbody></table><p>这里的 <code>cr</code> 是代码符号重命名。本文环境使用补全预设 <code>enter</code>；没有可接受项时，回车按通常方式换行。</p><h3 id="内置终端" tabindex="-1"><a class="header-anchor" href="#内置终端" aria-hidden="true">#</a> 内置终端</h3><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>:terminal</code></td><td>在 Neovim 内运行 shell</td><td>Terminal</td><td>命令行；原生</td></tr><tr><td><code>空格 → f → t</code></td><td>打开项目根目录的终端</td><td>Terminal in root directory</td><td>普通；LazyVim</td></tr><tr><td><code>i</code></td><td>给终端里的程序输入</td><td>Insert</td><td>终端 Buffer 的普通模式；原生</td></tr><tr><td>先 <code>Ctrl+\\</code>，再 <code>Ctrl+n</code></td><td>返回 Neovim 普通模式</td><td>Terminal to Normal</td><td>终端输入模式；原生</td></tr></tbody></table><p>Paseo 的外层终端与 Neovim 内置终端是两层界面，详见<a href="#%E5%9C%A8%E7%BC%96%E8%BE%91%E5%99%A8%E9%87%8C%E8%BF%90%E8%A1%8C%E7%BB%88%E7%AB%AF">在编辑器里运行终端</a>。</p><h3 id="帮助" tabindex="-1"><a class="header-anchor" href="#帮助" aria-hidden="true">#</a> 帮助</h3><table><thead><tr><th>按键或命令</th><th>作用</th><th>英文助记</th><th>模式与来源</th></tr></thead><tbody><tr><td><code>nvim --clean +Tutor</code></td><td>打开原生交互教程</td><td>Tutor</td><td>外层终端；原生</td></tr><tr><td><code>:help i</code></td><td>查按键 i 的作用</td><td>Help</td><td>Neovim 命令行；原生</td></tr><tr><td><code>:help motion</code></td><td>查光标移动主题</td><td>Help</td><td>Neovim 命令行；原生</td></tr><tr><td><code>:help text-objects</code></td><td>查文本对象主题</td><td>Help</td><td>Neovim 命令行；原生</td></tr><tr><td><code>:help windows</code></td><td>查窗口主题</td><td>Help</td><td>Neovim 命令行；原生</td></tr><tr><td>按空格，稍停</td><td>查看空格前缀菜单</td><td>Which-key</td><td>普通模式；LazyVim</td></tr><tr><td><code>空格 → l</code></td><td>查看插件管理界面</td><td>Lazy，插件管理器名称</td><td>普通模式；LazyVim</td></tr></tbody></table><p>在支持页内链接的 Markdown 预览中可点目录跳转。直接用 Neovim 读这份文档时，可以输入 <code>/保存</code>、<code>/分屏</code> 或 <code>/ciw</code>，回车后用 <code>n</code> 继续查找。查带符号的字面按键可用 <code>\\V</code>，例如 <code>/\\V[b</code> 查找 <code>[b</code>。</p><h2 id="从头学习" tabindex="-1"><a class="header-anchor" href="#从头学习" aria-hidden="true">#</a> 从头学习</h2><p>这一部分使用原生命令完成一次编辑流程。熟悉后，再用速查表里的 LazyVim 组合键加快操作。</p><p>练习路线：</p><ol><li><a href="#_1-%E5%87%86%E5%A4%87%E7%BB%83%E4%B9%A0%E7%9B%AE%E5%BD%95">创建练习目录</a>，分清模式与按键记法。</li><li><a href="#_4-%E8%BE%93%E5%85%A5%E5%B9%B6%E4%BF%9D%E5%AD%98%E7%AC%AC%E4%B8%80%E4%BB%BD%E6%96%87%E4%BB%B6">输入并保存</a>，练习移动、修改、复制与搜索。</li><li><a href="#_7-%E5%90%8C%E4%B8%80%E7%BC%93%E5%86%B2%E5%8C%BA%E7%9A%84%E5%A4%9A%E4%B8%AA%E7%AA%97%E5%8F%A3">观察分屏同步</a>，打开第二份文件。</li><li><a href="#_9-%E4%BF%9D%E5%AD%98%E5%B9%B6%E9%AA%8C%E8%AF%81%E7%BB%93%E6%9E%9C">检查最终结果</a>。</li></ol><h3 id="_1-准备练习目录" tabindex="-1"><a class="header-anchor" href="#_1-准备练习目录" aria-hidden="true">#</a> 1. 准备练习目录</h3><p>先在终端创建独立的练习目录。以下 shell 示例适用于 Linux／macOS；在 Paseo 中选择 <strong>Terminal／终端</strong>后输入：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">mkdir</span> <span class="token parameter variable">-p</span> ~/nvim-practice
<span class="token builtin class-name">cd</span> ~/nvim-practice
nvim practice.md
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>下面假定 <code>practice.md</code> 是一个空白的新文件。如果已经存在练习内容，换一个未使用的文件名，再跟随操作。</p><p><strong>预期结果：</strong> 打开一个空白编辑区域，显示新文件名称，通常处于 Normal 模式。准备新 Buffer 后，执行保存才会创建磁盘文件。</p><h3 id="_2-分清模式与工作区" tabindex="-1"><a class="header-anchor" href="#_2-分清模式与工作区" aria-hidden="true">#</a> 2. 分清模式与工作区</h3><p>Neovim 是模态编辑器（Modal editor）。同一个文件里，按键会根据模式解释成输入文字或执行命令。</p><table><thead><tr><th>模式</th><th>作用</th><th>进入与退出</th></tr></thead><tbody><tr><td>Normal：普通模式</td><td>移动、复制、删除和使用组合键</td><td>编辑启动后通常处于此模式</td></tr><tr><td>Insert：插入模式</td><td>输入文字</td><td>普通模式按 <code>i</code> 等进入，<code>Esc</code> 返回</td></tr><tr><td>Visual：可视模式</td><td>先选中文字，再操作</td><td><code>v</code>、<code>V</code> 或 <code>Ctrl+v</code> 进入，<code>Esc</code> 取消</td></tr><tr><td>Command-line：命令行模式</td><td>输入保存、搜索等命令</td><td>普通模式按 <code>:</code>、<code>/</code>、<code>?</code>，回车执行或 <code>Esc</code> 取消</td></tr></tbody></table><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Normal → i → Insert → 输入文字 → Esc → Normal
Normal → v → Visual → 选择文字 → y 复制 → Normal
Normal → : → 输入命令 → 回车执行
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其他概念各管一件事：</p><table><thead><tr><th>概念</th><th>英文</th><th>含义</th></tr></thead><tbody><tr><td>编辑模式</td><td>Mode</td><td>当前按键如何解释</td></tr><tr><td>缓冲区</td><td>Buffer</td><td>文件在内存里的编辑内容；也可以是帮助、终端等特殊内容</td></tr><tr><td>窗口</td><td>Window</td><td>显示一个 Buffer 的区域，可以分屏</td></tr><tr><td>标签页</td><td>Tabpage</td><td>一组窗口布局</td></tr><tr><td>工作目录</td><td>Working directory／cwd</td><td>相对文件路径的起点，用 <code>:pwd</code> 查看</td></tr><tr><td>项目根目录</td><td>Project root</td><td>根据 Git、语言服务等识别的项目范围</td></tr><tr><td>Paseo 工作区</td><td>Workspace</td><td>Paseo 中组织项目、聊天、终端的环境</td></tr></tbody></table><p>切换模式不会创建工作区或文件。Paseo 把终端画面和按键连接到运行 Neovim 的主机；编辑和保存的也是那台主机上的文件。</p><h3 id="_3-看懂按键记法" tabindex="-1"><a class="header-anchor" href="#_3-看懂按键记法" aria-hidden="true">#</a> 3. 看懂按键记法</h3><p>把文档写法翻译成真实动作即可，功能还要结合模式判断。</p><table><thead><tr><th>文档写法</th><th>实际按法</th></tr></thead><tbody><tr><td><code>gg</code></td><td>按一下 g，松开，再按一下 g</td></tr><tr><td><code>G</code></td><td>输入大写 G，通常是 Shift+g</td></tr><tr><td><code>Ctrl+r</code>／<code>&lt;C-r&gt;</code></td><td>按住 Ctrl，按一下 r，再松开</td></tr><tr><td><code>&lt;S-h&gt;</code></td><td>Shift+h，即大写 H</td></tr><tr><td><code>&lt;A-j&gt;</code></td><td>Alt+j</td></tr><tr><td><code>&lt;Esc&gt;</code></td><td>按 Escape 键</td></tr><tr><td><code>&lt;CR&gt;</code></td><td>Carriage Return，按一次回车</td></tr><tr><td><code>&lt;leader&gt;</code></td><td>前缀键，LazyVim 默认是空格</td></tr><tr><td><code>&lt;leader&gt;ff</code></td><td>依次按空格、f、f</td></tr><tr><td><code>:w&lt;CR&gt;</code></td><td>输入英文冒号和 w，再按回车</td></tr></tbody></table><blockquote><p><strong>容易混淆</strong>：<code>&lt;CR&gt;</code> 是回车，<code>&lt;C-r&gt;</code> 是 Ctrl+r。</p></blockquote><p>箭头、尖括号中的名称属于说明记号，操作时转换为对应按键。</p><p>在 Paseo 中先点终端，让它获得键盘焦点。执行字母命令时使用英文输入法；输入中文正文时再切回中文。</p><h3 id="_4-输入并保存第一份文件" tabindex="-1"><a class="header-anchor" href="#_4-输入并保存第一份文件" aria-hidden="true">#</a> 4. 输入并保存第一份文件</h3><p>按 <code>i</code>，输入三行文字：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code><span class="token title important"><span class="token punctuation">#</span> Neovim 学习记录</span>
apple banana cherry
今天练习输入、修改和保存。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后按 <code>Esc</code>，输入 <code>:w</code>，按回车。</p><p><strong>预期结果：</strong> 文字保留在编辑区域，回到普通模式，出现写入成功的提示；文件保存在练习目录中。可用 <code>:pwd</code> 查看目录。</p><p>编辑流程可以理解为：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>磁盘文件 → 加载到 Buffer → 修改内存中的文字 → 保存到磁盘
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>未命名 Buffer 第一次保存时可执行 <code>:w notes.md</code>。文件后缀按内容选择：<code>.md</code> 适合笔记与文档，<code>.txt</code> 是纯文本，<code>.py</code> 是 Python 代码，<code>.lua</code> 是 Lua 代码。文件类型与编辑模式是不同维度。</p><p>LazyVim 默认开启 <code>autowrite</code>，部分操作会触发写入。养成在明确阶段执行 <code>:w</code> 的习惯；<code>:q!</code> 不会回退已经保存的内容。</p><h3 id="_5-移动与修改文字" tabindex="-1"><a class="header-anchor" href="#_5-移动与修改文字" aria-hidden="true">#</a> 5. 移动与修改文字</h3><p>先按 <code>gg</code> 到第一行，再按 <code>j</code> 到第二行，按 <code>0</code> 到这一行开头。</p><p>此时可以用 <code>w</code>、<code>b</code>、<code>e</code> 观察单词移动。正式修改前，再用 <code>gg</code>、<code>j</code>、<code>0</code> 回到 <code>apple</code> 开头。</p><p>依次按 <code>c</code>、<code>i</code>、<code>w</code>，输入 <code>orange</code>，再按 <code>Esc</code>。</p><p><strong>预期结果：</strong> 第二行变为：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>orange banana cherry
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>ciw</code> 是 Change inner word：选择整个当前单词，删除后进入插入模式。按 <code>u</code>，它恢复为 <code>apple</code>；在普通模式按 <code>Ctrl+r</code>，又恢复为 <code>orange</code>。若客户端未传递 Ctrl+r，可用原生命令 <code>:redo</code> 完成这一步。</p><p>模式改变的是按键含义：普通模式的 <code>i</code> 会进入插入，插入模式的 <code>i</code> 会写出字母。状态栏能帮助判断当前模式。</p><h3 id="_6-选择复制与搜索" tabindex="-1"><a class="header-anchor" href="#_6-选择复制与搜索" aria-hidden="true">#</a> 6. 选择复制与搜索</h3><p>继续在第二行练习：</p><ol><li>按 <code>yy</code>，再按 <code>p</code>：复制整行并在下面粘贴，暂时多出一行。</li><li>按 <code>u</code>：撤销这次粘贴，恢复为三行。</li><li>按 <code>gg</code>、<code>j</code> 回第二行，按 <code>V</code>，再按 <code>j</code>：选中第二、三行。</li><li>按 <code>y</code> 复制，按 <code>G</code> 到末尾，再按 <code>p</code>：把这两行复制到文件末尾。</li><li>按 <code>u</code>：再次撤销粘贴，文件恢复三行。</li></ol><p>复制、剪切使用寄存器（Register）暂存内容，<code>p</code> 取出内容。内部寄存器与手机或电脑的系统剪贴板是两层机制，跨应用操作见附录。</p><p>现在输入 <code>/a</code> 并回车，用 <code>n</code>、<code>N</code> 在第二行多个 a 之间移动。搜索只有一个匹配时，继续查找可能绕回同一位置。</p><p>接着执行：</p><div class="language-vim line-numbers-mode" data-ext="vim"><pre class="language-vim"><code><span class="token punctuation">:</span><span class="token operator">%</span>s<span class="token operator">/</span>banana<span class="token operator">/</span>grape<span class="token operator">/</span>gc
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>确认时按 <code>y</code>。</p><p><strong>预期结果：</strong> 第二行变为 <code>orange grape cherry</code>。输入 <code>:w</code> 保存。</p><p>替换命令的 <code>%</code> 表示全部行，<code>s</code> 是 Substitute，<code>g</code> 表示每行所有匹配，<code>c</code> 是 Confirm、逐项确认。搜索输入是正则表达式，初学先用普通文字。</p><h3 id="_7-同一缓冲区的多个窗口" tabindex="-1"><a class="header-anchor" href="#_7-同一缓冲区的多个窗口" aria-hidden="true">#</a> 7. 同一缓冲区的多个窗口</h3><p>先按 <code>gg</code>，再执行：</p><div class="language-vim line-numbers-mode" data-ext="vim"><pre class="language-vim"><code><span class="token punctuation">:</span><span class="token keyword">vsplit</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>预期结果：</strong> 出现左右两个窗口，都显示同一个练习文件。新窗口的位置由配置决定。</p><p>在当前窗口按 <code>gg</code>、<code>A</code>，追加 <code>（同步测试）</code>，再按 <code>Esc</code>。另一窗口也会显示这次修改，即使尚未保存。</p><p>原因是：多个窗口是同一份 Buffer 内容的多个视图。</p><table><thead><tr><th>项目</th><th>是否共享</th></tr></thead><tbody><tr><td>编辑中的文字、未保存状态</td><td>共享</td></tr><tr><td>撤销与重做历史</td><td>共享</td></tr><tr><td>光标与滚动位置</td><td>默认各自保留；增删行时位置可能随文本调整</td></tr></tbody></table><p>在 LazyVim 中用 <code>Ctrl+h</code>、<code>Ctrl+l</code> 切换窗口。原生 Neovim 可以先按 <code>Ctrl+w</code>，再按 <code>h</code> 或 <code>l</code>。两个窗口分别执行 <code>:echo bufnr()</code>，相同编号表示显示同一个 Buffer。</p><p>此时执行一次 <code>:q!</code>：只关闭当前窗口，剩下的窗口仍保留追加后的标题和未保存状态。再执行 <code>:w</code> 保存。</p><p>这解释了为什么“关闭窗口”和“丢弃 Buffer 修改”需要分开理解。只有一个窗口、没有其他待处理 Buffer 的常见入门场景中，<code>:q!</code> 才会退出编辑器并放弃未保存改动。</p><p>分别在两个 Paseo 终端启动 Neovim，属于两个独立实例，通常各自维护 Buffer；另一个实例需通过磁盘保存、重载等方式看到变化。</p><h3 id="_8-打开另一个文件" tabindex="-1"><a class="header-anchor" href="#_8-打开另一个文件" aria-hidden="true">#</a> 8. 打开另一个文件</h3><p>在剩下的窗口中执行：</p><div class="language-vim line-numbers-mode" data-ext="vim"><pre class="language-vim"><code><span class="token punctuation">:</span><span class="token keyword">vsplit</span> todo<span class="token operator">.</span>md
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>新窗口准备了另一份文件 Buffer。按 <code>i</code>，输入 <code>今天完成第一次 Neovim 练习。</code>，按 <code>Esc</code>，执行 <code>:w</code>。</p><p><strong>预期结果：</strong> 两个窗口显示不同文件；修改 <code>todo.md</code> 不会改变 <code>practice.md</code>。</p><p>用 <code>:ls</code> 查看 Buffer 列表，也可以用 LazyVim 的 <code>空格 → ,</code> 选择文件。<code>空格 → b → d</code> 关闭 Buffer，<code>空格 → w → d</code> 关闭窗口；磁盘文件保留。</p><p>Neovim 上方一排文件名在 LazyVim 中通常是 Buffer 列表。真正的 Tabpage 管理整组窗口布局，可用 <code>:tabnew</code> 新建，<code>gt/gT</code> 切换。</p><h3 id="_9-保存并验证结果" tabindex="-1"><a class="header-anchor" href="#_9-保存并验证结果" aria-hidden="true">#</a> 9. 保存并验证结果</h3><p>执行 <code>:wqa</code>，保存并退出所有窗口。无法保存时会提示原因，处理后再退出。</p><p>回到外层终端检查：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> practice.md
<span class="token function">cat</span> todo.md
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>如果完整执行了上述必做步骤，<code>practice.md</code> 应为：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code><span class="token title important"><span class="token punctuation">#</span> Neovim 学习记录（同步测试）</span>
orange grape cherry
今天练习输入、修改和保存。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>todo.md</code> 应只有这一行：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>今天完成第一次 Neovim 练习。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>再运行 <code>nvim practice.md</code>，可以继续编辑。若结果不同，先检查是否执行了练习中的撤销操作、确认替换，以及最终保存。</p><h2 id="进阶理解" tabindex="-1"><a class="header-anchor" href="#进阶理解" aria-hidden="true">#</a> 进阶理解</h2><h3 id="操作符与文本对象" tabindex="-1"><a class="header-anchor" href="#操作符与文本对象" aria-hidden="true">#</a> 操作符与文本对象</h3><p>Neovim 命令可以组合，基本形式是：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>次数 + 操作符 + 移动范围或文本对象
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>d</code> 是 Delete，<code>y</code> 是 Yank，<code>c</code> 是 Change。按下操作符后，编辑器等待范围，这叫 <strong>Operator-pending</strong>。</p><ul><li><code>dw</code>：从光标删除到下一单词开头。</li><li><code>d$</code>：删除到行尾。</li><li><code>y$</code>：复制到行尾。</li><li><code>dd/yy/cc</code>：重复操作符，作用于整行。</li><li><code>3dd</code>：从当前行开始删除三行。</li></ul><p>文本对象（Text object）描述完整单元：<code>iw</code> 是 Inner word，<code>aw</code> 是 A word、通常连同相邻空白；<code>i&quot;</code> 表示双引号内部。</p><p>例如，在 <code>message = &quot;hello world&quot;</code> 的引号内容中按 <code>ci&quot;</code>，输入新内容再按 <code>Esc</code>，两侧引号保留。在另一个位置按 <code>.</code>，可以重复上一次修改。</p><p>这里的 <code>i</code> 表示 Inner／Inside，和单独按 <code>i</code> 进入 Insert 的上下文不同。重复操作符的整行规则适用于 <code>dd/yy</code> 等组合，不能套用到所有重复字母上。</p><h3 id="替换模式与选择模式" tabindex="-1"><a class="header-anchor" href="#替换模式与选择模式" aria-hidden="true">#</a> 替换模式与选择模式</h3><p><code>rX</code> 是一次替换，完成后仍在 Normal；<code>R</code> 会进入 <strong>Replace</strong>，连续覆盖输入，直到按 <code>Esc</code>。</p><p><strong>Select</strong> 模式允许输入文字直接替换选中内容，部分代码片段占位符会使用它。初学先掌握 Normal、Insert、Visual、Command-line 四种模式，再认识这些附加状态。</p><h3 id="代码能力的三个组成" tabindex="-1"><a class="header-anchor" href="#代码能力的三个组成" aria-hidden="true">#</a> 代码能力的三个组成</h3><p>语法高亮、语言服务、格式化是不同能力：</p><table><thead><tr><th>能力</th><th>作用</th><th>常见实现</th></tr></thead><tbody><tr><td>语法解析与高亮</td><td>识别代码结构、提供高亮等</td><td>Treesitter 及语言解析器</td></tr><tr><td>语言服务</td><td>理解符号，提供跳转、引用、重命名、诊断等</td><td>Language Server Protocol，LSP</td></tr><tr><td>格式化</td><td>按规则重新排版</td><td>对应格式化程序</td></tr></tbody></table><p>因此，有 Python 高亮不等于已经具备 Python 语言服务；按 <code>空格 → c → f</code> 也需要当前语言有可用格式化工具。<code>Ctrl+o</code> 返回跳转历史则是原生功能，不依赖 LSP。</p><p>作者环境已验证 Lua 服务初始化和 Lua 格式化。可以用一个 <code>example.lua</code> 文件，逐步练习跳转、返回和格式化；具体交互的验证范围见附录。</p><h3 id="在编辑器里运行终端" tabindex="-1"><a class="header-anchor" href="#在编辑器里运行终端" aria-hidden="true">#</a> 在编辑器里运行终端</h3><p>外层终端负责启动 <code>nvim</code>；在 Neovim 中执行 <code>:terminal</code>，会再打开一个终端 Buffer。进入 <strong>Terminal</strong> 输入模式后，按键交给其中的程序。</p><p>返回 Neovim 普通模式：先按 <code>Ctrl+\\</code>，再按 <code>Ctrl+n</code>。随后可以移动和选择输出，按 <code>i</code> 继续向 shell 输入。</p><p>这里的退出方式和 Insert 不同。LazyVim 的 <code>空格 → f → t</code> 是项目根目录终端入口。</p><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题" aria-hidden="true">#</a> 常见问题</h2><table><thead><tr><th>现象</th><th>优先检查与处理</th></tr></thead><tbody><tr><td><code>i</code>、<code>dd</code> 或 <code>:w</code> 出现在正文中</td><td>当前可能在 Insert；按 <code>Esc</code>，再使用普通模式命令</td></tr><tr><td>无法直接输入文字</td><td>看状态栏，可能在 Normal；按 <code>i</code> 开始输入</td></tr><tr><td>看见 <code>&lt;CR&gt;</code>，不知道按哪个键</td><td>它是回车；<code>&lt;C-r&gt;</code> 才是 Ctrl+r</td></tr><tr><td>保存到了意料之外的位置</td><td>执行 <code>:pwd</code>，必要时使用绝对路径</td></tr><tr><td><code>ff</code> 和目录中的文件范围不同</td><td>区分项目根目录与 cwd，比较 <code>ff/fF</code></td></tr><tr><td><code>p</code> 粘贴了刚删除的内容</td><td>默认寄存器可能被删除操作更新</td></tr><tr><td>关闭一个分屏后文字修改还在</td><td>另一窗口仍显示同一 Buffer；关闭窗口和还原内容是两件事</td></tr><tr><td><code>:q!</code> 没有回到以前的磁盘内容</td><td>它不回退已保存版本；已经保存的修改可通过撤销后再保存来调整</td></tr><tr><td>终端中按 Esc 没回到普通模式</td><td>使用 <code>Ctrl+\\</code>，然后 <code>Ctrl+n</code></td></tr><tr><td>某语言没有跳转或格式化</td><td>核实该语言的服务、格式化工具及功能支持</td></tr><tr><td>组合键触发了客户端操作</td><td>确认终端焦点和客户端对特殊键的传递方式</td></tr></tbody></table><h2 id="继续练习与参考" tabindex="-1"><a class="header-anchor" href="#继续练习与参考" aria-hidden="true">#</a> 继续练习与参考</h2><h3 id="原生交互教程" tabindex="-1"><a class="header-anchor" href="#原生交互教程" aria-hidden="true">#</a> 原生交互教程</h3><p>外层终端运行 <code>nvim --clean +Tutor</code>，可进入原生交互教程。<code>--clean</code> 只在这次启动中跳过 LazyVim；其中不加载空格查文件等 LazyVim 组合键。退出后正常运行 <code>nvim</code> 即恢复原配置。</p><p>在编辑器内使用 <code>:help i</code>、<code>:help motion</code>、<code>:help text-objects</code>、<code>:help windows</code> 查看主题；帮助也是 Buffer／Window，可用 <code>:q</code> 关闭。</p><h3 id="学习检查清单" tabindex="-1"><a class="header-anchor" href="#学习检查清单" aria-hidden="true">#</a> 学习检查清单</h3><p>按自己实际完成的操作勾选：</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> 独立完成正文流程，检查两个最终文件。</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> 观察模式提示，熟练使用插入、撤销、选择和保存。</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> 练习 <code>diw</code>、<code>ci&quot;</code>、<code>.</code> 与矩形选择。</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> 使用速查表完成项目文件查找、全文搜索和窗口切换。</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> 用实际 Lua 文件验证补全、跳转、重命名和格式化。</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> 记录实际 Paseo 客户端的特殊键、字体与剪贴板体验。</label></li></ul><h3 id="官方参考" tabindex="-1"><a class="header-anchor" href="#官方参考" aria-hidden="true">#</a> 官方参考</h3>`,156),u={href:"https://neovim.io/doc/user/usr_02/",target:"_blank",rel:"noopener noreferrer"},b={href:"https://neovim.io/doc/user/usr_03/",target:"_blank",rel:"noopener noreferrer"},f={href:"https://neovim.io/doc/user/usr_04/",target:"_blank",rel:"noopener noreferrer"},E={href:"https://neovim.io/doc/user/insert/",target:"_blank",rel:"noopener noreferrer"},v={href:"https://neovim.io/doc/user/visual/",target:"_blank",rel:"noopener noreferrer"},g={href:"https://neovim.io/doc/user/editing/",target:"_blank",rel:"noopener noreferrer"},y={href:"https://neovim.io/doc/user/cmdline/",target:"_blank",rel:"noopener noreferrer"},B={href:"https://neovim.io/doc/user/windows/",target:"_blank",rel:"noopener noreferrer"},k={href:"https://neovim.io/doc/user/terminal/",target:"_blank",rel:"noopener noreferrer"},A={href:"https://www.lazyvim.org/keymaps",target:"_blank",rel:"noopener noreferrer"},x={href:"https://paseo.sh/docs/cli#terminals",target:"_blank",rel:"noopener noreferrer"},w=r(`<h2 id="附录" tabindex="-1"><a class="header-anchor" href="#附录" aria-hidden="true">#</a> 附录</h2><h3 id="作者环境与定制" tabindex="-1"><a class="header-anchor" href="#作者环境与定制" aria-hidden="true">#</a> 作者环境与定制</h3><p>以下是作者机器的部署记录，主文练习不要求读者采用这套系统级安装方式。</p><table><thead><tr><th>项目</th><th>作者环境</th></tr></thead><tbody><tr><td>操作系统</td><td>Ubuntu 24.04</td></tr><tr><td>Neovim / LazyVim</td><td>0.12.6 / 16.0.2</td></tr><tr><td>Paseo 服务端</td><td>0.15.2；客户端版本与界面需单独确认</td></tr><tr><td>全局配置</td><td><code>/etc/xdg/nvim</code></td></tr><tr><td>共享插件、解析器和语言工具</td><td><code>/usr/local/share/lazyvim</code></td></tr><tr><td>本机专用维护命令</td><td><code>sudo lazyvim-update</code>，由作者的安装脚本提供</td></tr></tbody></table><p>日常快捷键、默认主题和主要编辑选项沿用 LazyVim 默认。自定义 <code>keymaps.lua</code>、<code>options.lua</code>、<code>autocmds.lua</code> 目前只有官方模板注释；没有手动启用额外语言或 AI Extras，默认内部功能仍会加载。</p><p>系统级共享安装调整了以下行为：</p><ul><li>配置、插件、解析器和语言工具由 root 管理；普通用户直接运行 <code>nvim</code>。</li><li>普通启动关闭自动安装、更新检查及 Mason 管理入口，管理员通过上述本机命令维护。因此通用教程中的 <code>:Mason</code>／<code>空格 → c → m</code> 在此环境的普通启动中未启用。</li><li>Lua 服务日志与生成的元数据写入各用户状态／缓存目录，适配只读共享安装。</li><li>解析器提前集中准备；普通启动不自动安装。</li><li>按稳定版规则加载 LazyVim，调整 Git 下载参数与并发，关闭新闻提示、LuaRocks 和项目级 <code>.lazy.lua</code> 附加插件配置。</li></ul><p><code>空格 → l</code> 可以查看插件管理界面；共享资源的更新统一使用 <code>sudo lazyvim-update</code>。该命令更新共享插件、解析器和语言工具，不升级 Neovim 主程序，也不是其他机器安装 LazyVim 后自动就有的命令。</p><p>主要定制位于全局配置下的 <code>lua/config/lazy.lua</code> 和 <code>lua/plugins/system.lua</code>。starter 的 <code>lua/plugins/example.lua</code> 开头直接返回空配置，里面展示的 Python、TypeScript 等示例未启用。</p><p>作者环境已安装 <code>lua-language-server</code>、Lua 格式化工具 <code>stylua</code> 和 Shell 格式化工具 <code>shfmt</code>；其他语言的完整智能支持按需配置。编辑历史、撤销记录、日志和缓存按用户隔离。</p><h3 id="客户端与验证范围" tabindex="-1"><a class="header-anchor" href="#客户端与验证范围" aria-hidden="true">#</a> 客户端与验证范围</h3><p>Paseo 使用链路：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>手机／电脑上的 Paseo 客户端
          ↓ 终端显示与按键传递
运行 Neovim + LazyVim 的主机
          ↓ 编辑和保存
该主机上的文件
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>服务器安装的 Nerd Font 和 GNOME 终端字体默认值，不会自动改变手机或浏览器的终端字体。编辑器内部的 <code>yy/p</code> 与跨应用系统剪贴板也要分别判断。</p><table><thead><tr><th>验证层级</th><th>当前记录</th></tr></thead><tbody><tr><td>已核对配置</td><td>常用 LazyVim 组合键、补全预设 <code>enter</code>、全局路径及维护策略</td></tr><tr><td>已实测</td><td>root、当前用户及另一普通账户启动；Lua 服务初始化、语法解析与格式化；补全组件加载</td></tr><tr><td>正文练习验证</td><td>在原生干净配置与本机 LazyVim 下运行正文练习，核对撤销／重做、确认替换、共享 Buffer 分屏、<code>:q!</code> 边界及两个最终文件内容</td></tr><tr><td>待客户端确认</td><td>实际 Paseo 客户端的 Esc/Ctrl/Alt 传递、补全候选选择、字体和跨应用剪贴板</td></tr></tbody></table><p>检查客户端时，先让终端获得焦点；确认特殊按键能传到主机，再判断编辑器功能。本文不预设不同 Paseo 客户端具有相同的键盘工具栏。</p><hr><p><em>最后更新：2026-11-16。</em></p>`,18);function C(_,L){const e=a("ExternalLinkIcon");return i(),n("div",null,[h,p,l(" more "),m,d("ul",null,[d("li",null,[d("a",u,[t("Neovim 官方入门"),o(e)])]),d("li",null,[d("a",b,[t("移动位置"),o(e)]),t("与"),d("a",f,[t("操作符、文本对象"),o(e)])]),d("li",null,[d("a",E,[t("插入和替换"),o(e)]),t("与"),d("a",v,[t("可视选择"),o(e)])]),d("li",null,[d("a",g,[t("文件编辑、保存与退出"),o(e)]),t("与"),d("a",y,[t("命令行模式"),o(e)])]),d("li",null,[d("a",B,[t("Buffer、窗口、标签页"),o(e)]),t("与"),d("a",k,[t("内置终端"),o(e)])]),d("li",null,[d("a",A,[t("LazyVim 官方键位"),o(e)]),t("与"),d("a",x,[t("Paseo 终端说明"),o(e)])])]),w])}const N=c(s,[["render",C],["__file","neovim-lazyvim.html.vue"]]);export{N as default};
